package com.lbos.commercecustomer.service; import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.client.PartnerVerificationClient;import com.lbos.commercecustomer.dto.request.ReplaceWishlistProductRequest;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.DuplicateResourceException;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.util.*;import org.junit.jupiter.api.Test; class WishlistServiceImplTest {private static RetailerEnrichmentSupport noRetailerEnrichment(){return new RetailerEnrichmentSupport(mock(PartnerVerificationClient.class),new FeignCallSupport());}@Test void duplicateIsRejected(){var r=mock(CustomerWishlistItemRepository.class);var p=mock(ProductRepository.class);var c=mock(ContextSupport.class);var customer=new CustomerProfile();customer.setId(UUID.randomUUID());when(c.customer()).thenReturn(customer);when(r.existsByCustomerIdAndProductId(customer.getId(),1L)).thenReturn(true);var s=new WishlistServiceImpl(r,p,c,new CommerceMapper(),noRetailerEnrichment());assertThrows(DuplicateResourceException.class,()->s.add(new ReplaceWishlistProductRequest(1L)));}@Test void membershipBoundaryEmpty(){var r=mock(CustomerWishlistItemRepository.class);var c=mock(ContextSupport.class);var customer=new CustomerProfile();customer.setId(UUID.randomUUID());when(c.customer()).thenReturn(customer);var s=new WishlistServiceImpl(r,mock(ProductRepository.class),c,new CommerceMapper(),noRetailerEnrichment());assertTrue(s.membership(List.of()).isEmpty());}}